//! Integration test for HLS fMP4 (EXT-X-MAP) streaming against an FFmpeg-generated
//! fixture served by real Nginx in Docker (RFC 8216 / #177).
//!
//! `#[ignore]` — depends on Docker environment and fixtures generated by
//! `./scripts/test-network-protocols.sh` at the repository root.
use protocols::hls::HlsStreamSource;
use std::io::Read;

fn env_or(key: &str, default: &str) -> String {
    std::env::var(key).unwrap_or_else(|_| default.to_string())
}

fn base_url() -> String {
    env_or("VRPLAYER_TEST_HTTP_URL_BASE", "http://127.0.0.1:18080")
}

#[test]
#[ignore]
fn hls_fmp4_reads_init_and_all_segments_from_real_server() {
    let m3u8_url = format!("{}/hls_fmp4/playlist.m3u8", base_url());
    let mut source =
        HlsStreamSource::open(&m3u8_url).expect("open should succeed against real HLS fMP4 stream");

    assert!(source.total_duration() > 0.0);

    let mut total = 0usize;
    let mut buf = vec![0u8; 16 * 1024];
    let mut first_chunk = true;

    loop {
        let n = source
            .read(&mut buf)
            .expect("read should not fail against real server");
        if n == 0 {
            break;
        }

        if first_chunk {
            first_chunk = false;
            // The stream MUST begin with an MP4 box containing the 'ftyp' major brand
            assert!(
                n >= 8,
                "first read chunk must contain at least 8 bytes for MP4 box header"
            );
            assert_eq!(
                &buf[4..8],
                b"ftyp",
                "stream must start with ftyp box from init.mp4"
            );
        }

        total += n;
    }

    if let Ok(expected_str) = std::env::var("VRPLAYER_TEST_HLS_FMP4_SIZE") {
        if let Ok(expected_size) = expected_str.trim().parse::<usize>() {
            assert_eq!(
                total, expected_size,
                "total bytes read ({total}) must match exact concatenated size of init.mp4 + *.m4s ({expected_size})"
            );
        }
    } else {
        assert!(
            total > 20_000,
            "expected init segment + media chunks, but only received {total} bytes"
        );
    }
}
